"""Deterministic synthetic dock and yard appointment data generator."""
from __future__ import annotations
import argparse, csv, hashlib, json, random, shutil
from collections import defaultdict
from datetime import datetime, timedelta, timezone
from pathlib import Path

TABLES = ('facilities docks yard_slots carriers vehicles labor_shifts capacity_calendars '
          'shipments handling_requirements appointments appointment_shipments dock_reservations '
          'yard_reservations labor_allocations checkin_events operational_events exceptions derived_metrics resource_utilization_metrics').split()
PROFILES = {'tiny': (1,5,50,250,7), 'starter': (2,20,1000,5000,14), 'full': (10,100,20000,100000,60)}
START = datetime(2026,10,22,tzinfo=timezone.utc)
CONFIG = json.loads((Path(__file__).resolve().parents[2] / 'config' / 'profiles.json').read_text(encoding='utf-8'))

def iso(x): return x.isoformat().replace('+00:00','Z')
def write_rows(path, table, rows):
    fields = sorted({k for r in rows for k in r}) if rows else ['id']
    with (path/f'{table}.csv').open('w', newline='', encoding='utf-8') as f:
        w=csv.DictWriter(f, fieldnames=fields, extrasaction='ignore'); w.writeheader(); w.writerows(rows)
    (path/f'{table}.json').write_text(json.dumps(rows, sort_keys=True, indent=2), encoding='utf-8')
def load_rows(path, table):
    with (path/f'{table}.csv').open(encoding='utf-8', newline='') as f: return list(csv.DictReader(f))
def ident(prefix, n, width=6): return f'{prefix}-{n:0{width}d}'

def generate(profile, seed=20261022):
    if profile not in PROFILES: raise ValueError(f'unknown profile: {profile}')
    nf, nd, na, ne, days = PROFILES[profile]; rng=random.Random(seed)
    t={x:[] for x in TABLES}; docks_by_fac=defaultdict(list); vehicle_by_id={}; ship_by_id={}
    # 1 facilities, docks, slots
    for f in range(1,nf+1):
        fid=ident('FAC',f,3); t['facilities'].append({'facility_id':fid,'name':f'Facility {f}','timezone':'UTC','effective_from':iso(START),'active':'true'})
    for d in range(1,nd+1):
        fac=ident('FAC',((d-1)%nf)+1,3); did=f'DOCK-{fac}-{d:03d}'
        # Cycle capability per facility, not globally: each facility must be able to
        # serve standard, refrigerated and hazardous appointments.
        local_dock_ordinal=((d-1)//nf)+1
        dtype=('REFRIGERATED' if local_dock_ordinal%5==4 else 'HAZMAT' if local_dock_ordinal%5==0 else 'STANDARD')
        r={'dock_id':did,'facility_id':fac,'dock_type':dtype,'length_m':str(18 if dtype!='STANDARD' else 12+(d%3)*3),'capacity_units':'1','active':'true'}; t['docks'].append(r); docks_by_fac[fac].append(r)
        for s in range(1,3): t['yard_slots'].append({'yard_slot_id':f'YARD-{fac}-{d:03d}-{s:02d}','facility_id':fac,'slot_type':'REEFER' if dtype=='REFRIGERATED' else 'GENERAL','capacity_units':'1','active':'true'})
    # 2 parties / shifts / capacity calendar
    nc=max(5,nf*4); nv=max(12,nd*3)
    for i in range(1,nc+1): t['carriers'].append({'carrier_id':ident('CAR',i,4),'name':f'Carrier {i}','scac':f'C{i:03d}','active':'true'})
    for i in range(1,nv+1):
        cap='REFRIGERATED' if i%7==0 else 'HAZMAT' if i%11==0 else 'STANDARD'; vid=ident('VEH',i,5)
        r={'vehicle_id':vid,'carrier_id':ident('CAR',((i-1)%nc)+1,4),'vehicle_type':'TRACTOR_TRAILER','length_m':str(12+(i%3)*3),'capability':cap,'active':'true'}; t['vehicles'].append(r); vehicle_by_id[vid]=r
    for f in range(1,nf+1):
        fid=ident('FAC',f,3)
        for day in range(days):
            date=(START+timedelta(days=day)).date().isoformat(); weekend=(START+timedelta(days=day)).weekday()>=5
            for shift,hour in [('DAY',6),('EVE',14)]:
                # Baseline labor supports one simultaneously active appointment per dock.
                # Peak congestion is still generated by fixed requested windows and dock type/size limits.
                sid=f'SHIFT-{fid}-{day+1:03d}-{shift}'; workers=max(2,len(docks_by_fac[fid])*int(CONFIG['baseline_labor_workers_per_dock']))
                t['labor_shifts'].append({'labor_shift_id':sid,'facility_id':fid,'shift_code':shift,'start_ts':iso(START+timedelta(days=day,hours=hour)),'end_ts':iso(START+timedelta(days=day,hours=hour+8)),'workers':str(workers),'skills':'STANDARD,REFRIGERATED,HAZMAT','status':'SCHEDULED'})
                t['capacity_calendars'].append({'calendar_id':f'CAL-{fid}-{date}-{shift}','facility_id':fid,'labor_shift_id':sid,'calendar_date':date,'dock_capacity':str(len(docks_by_fac[fid])),'yard_capacity':str(len(docks_by_fac[fid])*2),'labor_capacity':str(workers),'effective_from':iso(START)})
    # 3 Shipments & requests allocated by deterministic earliest compatible resource sweep.
    # Weekdays are weighted 3:1 over weekends; all dates in the profile remain eligible.
    occupied=defaultdict(list); yard_occupied=defaultdict(list); labor_occupied=defaultdict(list); appointment_rows=[]
    demand_days=[day for day in range(days) for _ in range(int(CONFIG['weekday_demand_weight']) if (START+timedelta(days=day)).weekday()<5 else 1)]
    for i in range(1,na+1):
        aid=f'APPT-{START.year}-{i:06d}'; shid=f'SHP-{START.year}-{i:06d}'; fac=ident('FAC',((i-1)%nf)+1,3); typ='REFRIGERATED' if i%13==0 else 'HAZMAT' if i%17==0 else 'STANDARD'; direction='INBOUND' if i%2 else 'OUTBOUND'; weight=5000+(i*137)%19000; pallets=4+(i%22); dur=45+pallets*4+(30 if typ!='STANDARD' else 0)
        t['shipments'].append({'shipment_id':shid,'carrier_id':ident('CAR',((i-1)%nc)+1,4),'direction':direction,'load_type':typ,'weight_kg':str(weight),'pallet_count':str(pallets),'status':'PLANNED'}); ship_by_id[shid]=t['shipments'][-1]
        t['handling_requirements'].append({'handling_requirement_id':f'HR-{START.year}-{i:06d}','shipment_id':shid,'requirement_type':typ,'requires_reefer':str(typ=='REFRIGERATED').lower(),'requires_hazmat_cert':str(typ=='HAZMAT').lower(),'service_minutes':str(dur)})
        # Five is coprime to all current weighted period lengths (17, 34, 146),
        # so every eligible day participates deterministically.
        # Seeded sampling keeps weekday/peak-hour weighting without modulo aliasing
        # between IDs, facilities, dates, hours and minutes.
        day=rng.choice(demand_days)
        hour=rng.choice(CONFIG['peak_hours']*int(CONFIG['peak_hour_weight'])+CONFIG['off_peak_hours'])
        requested=START+timedelta(days=day,hours=hour,minutes=rng.randrange(60)); start=requested; end=start+timedelta(minutes=dur)
        # Rotate within the matching fleet while guaranteeing the load capability.
        fleet=[v for v in t['vehicles'] if v['capability']==typ]; vehicle=fleet[(i-1)%len(fleet)]
        compatible=[d for d in docks_by_fac[fac] if d['dock_type']==typ and float(d['length_m'])>=float(vehicle['length_m'])]
        yard_candidates=[y for y in t['yard_slots'] if y['facility_id']==fac and (typ!='REFRIGERATED' or y['slot_type']=='REEFER')]
        sid=f'SHIFT-{fac}-{day+1:03d}-'+('DAY' if hour<14 else 'EVE')
        shift=next(s for s in t['labor_shifts'] if s['labor_shift_id']==sid)
        chosen=None; allocation_reason='ALLOCATED'
        if not compatible:
            allocation_reason='NO_COMPATIBLE_DOCK'
        for d in compatible:
            if any(start < e and end > s for s,e in occupied[d['dock_id']]): continue
            yard=next((y for y in yard_candidates if not any(start-timedelta(minutes=30) < e and end > s for s,e in yard_occupied[y['yard_slot_id']])), None)
            concurrent=sum(start < e and end > s for s,e in labor_occupied[sid])
            if yard and concurrent < int(shift['workers']): chosen=(d,yard); break
        if not chosen and compatible:
            free_docks=[d for d in compatible if not any(start < e and end > s for s,e in occupied[d['dock_id']])]
            if not free_docks: allocation_reason='DOCK_OCCUPIED'
            elif not any(not any(start-timedelta(minutes=30) < e and end > s for s,e in yard_occupied[y['yard_slot_id']]) for y in yard_candidates): allocation_reason='NO_YARD_CAPACITY'
            else: allocation_reason='INSUFFICIENT_QUALIFIED_LABOR'
        status='CONFIRMED' if chosen else 'WAITLISTED'; vid=ident('VEH',((i-1)%nv)+1,5)
        ap={'appointment_id':aid,'facility_id':fac,'vehicle_id':vehicle['vehicle_id'],'appointment_type':direction,'requested_start_ts':iso(requested),'scheduled_start_ts':iso(start) if chosen else '','scheduled_end_ts':iso(end) if chosen else '','status':status,'allocation_reason':allocation_reason,'service_minutes':str(dur),'created_ts':iso(START)}; t['appointments'].append(ap); appointment_rows.append(ap)
        t['appointment_shipments'].append({'appointment_id':aid,'shipment_id':shid,'sequence_no':'1'})
        if chosen:
            dock,y=chosen; occupied[dock['dock_id']].append((start,end)); yard_occupied[y['yard_slot_id']].append((start-timedelta(minutes=30),end)); labor_occupied[sid].append((start,end)); rid=f'RES-DOCK-{START.year}-{i:06d}'
            t['dock_reservations'].append({'dock_reservation_id':rid,'appointment_id':aid,'dock_id':dock['dock_id'],'start_ts':iso(start),'end_ts':iso(end),'status':'RESERVED'})
            t['yard_reservations'].append({'yard_reservation_id':f'RES-YARD-{START.year}-{i:06d}','appointment_id':aid,'yard_slot_id':y['yard_slot_id'],'start_ts':iso(start-timedelta(minutes=30)),'end_ts':iso(end),'status':'RESERVED'})
            t['labor_allocations'].append({'labor_allocation_id':f'LABALLOC-{START.year}-{i:06d}','appointment_id':aid,'labor_shift_id':sid,'workers_required':'1','skill':typ,'status':'ALLOCATED'})
    # 4 operational discrete events (five unique semantic events per appointment; target must divide, profiles do)
    event_types=['REQUESTED','CONFIRMED','CHECKED_IN','SERVICE_STARTED','SERVICE_COMPLETED']; evn=0
    for ap in appointment_rows:
        base=datetime.fromisoformat((ap['scheduled_start_ts'] or ap['requested_start_ts']).replace('Z','+00:00')); i=int(ap['appointment_id'][-6:]); no_show=(i%37==1 and ap['status']=='CONFIRMED'); arrival=base+timedelta(minutes=(-20 if i%5==0 else 0 if i%5==1 else 15))
        actual_end=arrival+timedelta(minutes=int(ap['service_minutes'])+(20 if i%19==0 else 0)); status='NO_SHOW' if no_show else ('COMPLETED' if ap['status']=='CONFIRMED' else 'WAITLISTED')
        ap['status']=status
        if no_show:
            no_show_ts=base+timedelta(minutes=30)
            seq_events=[('REQUESTED',datetime.fromisoformat(ap['created_ts'].replace('Z','+00:00'))),('CONFIRMED',base-timedelta(hours=2)),('GATE_EXPECTED',base),('NO_SHOW',no_show_ts),('EXCEPTION_RECORDED',no_show_ts+timedelta(minutes=1))]
        elif ap['status']=='WAITLISTED':
            seq_events=[('REQUESTED',datetime.fromisoformat(ap['created_ts'].replace('Z','+00:00'))),('WAITLISTED',base),('CAPACITY_CHECKED',base+timedelta(minutes=1)),('WAITLIST_REVIEWED',base+timedelta(minutes=2)),('WAITLIST_FINALIZED',base+timedelta(minutes=3))]
        else:
            seq_events=[('REQUESTED',datetime.fromisoformat(ap['created_ts'].replace('Z','+00:00'))),('CONFIRMED',base-timedelta(hours=2)),('CHECKED_IN',arrival),('SERVICE_STARTED',arrival+timedelta(minutes=5)),('SERVICE_COMPLETED',actual_end)]
        for seq,(etype,ts) in enumerate(seq_events,1):
            evn+=1; eid=f'EVT-{START.year}-{evn:07d}'; t['operational_events'].append({'event_id':eid,'appointment_id':ap['appointment_id'],'event_type':etype,'event_ts':iso(ts),'sequence_no':str(seq),'source':'SIMULATOR'})
            if etype in ('CHECKED_IN','NO_SHOW'): t['checkin_events'].append({'checkin_event_id':f'CHECK-{ap["appointment_id"]}-{seq:02d}','appointment_id':ap['appointment_id'],'event_type':etype,'event_ts':iso(ts),'arrival_class':'NO_SHOW' if no_show else ('EARLY' if arrival<base else 'ON_TIME' if arrival==base else 'LATE')})
        t['derived_metrics'].append({'appointment_id':ap['appointment_id'],'scheduled_service_minutes':ap['service_minutes'],'actual_service_minutes':'0' if no_show else str(int((actual_end-arrival).total_seconds()/60)),'waiting_minutes':'0' if no_show else str(max(0,int((arrival-base).total_seconds()/60))),'turnaround_minutes':'0' if no_show else str(int((actual_end-arrival).total_seconds()/60)),'appointment_status':status})
    assert evn==ne, (evn,ne)
    # Facility utilization is reconciled directly from reservations and labor capacity, never randomized.
    dock_fac={r['dock_id']:r['facility_id'] for r in t['docks']}; yard_fac={r['yard_slot_id']:r['facility_id'] for r in t['yard_slots']}
    dock_min=defaultdict(int); yard_min=defaultdict(int)
    for r in t['dock_reservations']: dock_min[dock_fac[r['dock_id']]] += int((dt:=datetime.fromisoformat(r['end_ts'].replace('Z','+00:00')) - datetime.fromisoformat(r['start_ts'].replace('Z','+00:00'))).total_seconds()//60)
    for r in t['yard_reservations']: yard_min[yard_fac[r['yard_slot_id']]] += int((datetime.fromisoformat(r['end_ts'].replace('Z','+00:00')) - datetime.fromisoformat(r['start_ts'].replace('Z','+00:00'))).total_seconds()//60)
    for f in t['facilities']:
        fid=f['facility_id']; dock_count=sum(d['facility_id']==fid for d in t['docks']); yard_count=sum(y['facility_id']==fid for y in t['yard_slots']); labor_cap=sum(int(s['workers'])*int((datetime.fromisoformat(s['end_ts'].replace('Z','+00:00'))-datetime.fromisoformat(s['start_ts'].replace('Z','+00:00'))).total_seconds()//60) for s in t['labor_shifts'] if s['facility_id']==fid)
        labor_used=sum(int(a['service_minutes']) for a in t['appointments'] if a['facility_id']==fid and a['status']!='WAITLISTED')
        t['resource_utilization_metrics'].append({'facility_id':fid,'period_start_ts':iso(START),'period_end_ts':iso(START+timedelta(days=days)),'dock_utilization':f'{dock_min[fid]/(dock_count*days*16*60):.6f}','yard_utilization':f'{yard_min[fid]/(yard_count*days*16*60):.6f}','labor_utilization':f'{labor_used/labor_cap:.6f}','no_show_count':str(sum(a['facility_id']==fid and a['status']=='NO_SHOW' for a in t['appointments'])),'exception_count':'0'})
    return t

def anomaly_rows(t):
    """Five isolated labelled violations; baseline is never mutated."""
    import copy; x=copy.deepcopy(t); gt=[]; apps={r['appointment_id']:r for r in x['appointments']}; res=x['dock_reservations']
    # 1 overlap one valid reservation at its same dock
    shipment_for_appointment={r['appointment_id']:r['shipment_id'] for r in x['appointment_shipments']}
    shipment_by_id={r['shipment_id']:r for r in x['shipments']}
    first=res[0]; first_type=shipment_by_id[shipment_for_appointment[first['appointment_id']]]['load_type']
    first_dock=next(d for d in x['docks'] if d['dock_id']==first['dock_id'])
    a=next(r for r in res[1:] if shipment_by_id[shipment_for_appointment[r['appointment_id']]]['load_type']==first_type and float(next(v for v in x['vehicles'] if v['vehicle_id']==apps[r['appointment_id']]['vehicle_id'])['length_m'])<=float(first_dock['length_m']))
    a['dock_id']=first['dock_id']; a['start_ts']=first['start_ts']; a['end_ts']=first['end_ts']; gt.append({'scenario_id':'SCN-001','issue_type':'DOCK_CAPACITY_EXCEEDED','cause_code':'FORCED_OVERLAP','affected_entity':'dock_reservations','affected_record_id':a['dock_reservation_id'],'expected_outcome':'OVERLAP_DETECTED'})
    # 2 point a valid shipment at a dock with a different capability.
    b=next(r for r in res if r not in (first,a) and shipment_by_id[shipment_for_appointment[r['appointment_id']]]['load_type'] == 'STANDARD')
    vehicle_b=next(v for v in x['vehicles'] if v['vehicle_id']==apps[b['appointment_id']]['vehicle_id'])
    b['dock_id']=next(d['dock_id'] for d in x['docks'] if d['dock_type']!='STANDARD' and float(d['length_m'])>=float(vehicle_b['length_m']))
    b['start_ts']='2026-12-31T22:00:00Z'; b['end_ts']='2026-12-31T23:00:00Z'
    gt.append({'scenario_id':'SCN-002','issue_type':'DOCK_INCOMPATIBLE','cause_code':'FORCED_INCOMPATIBLE_DOCK','affected_entity':'dock_reservations','affected_record_id':b['dock_reservation_id'],'expected_outcome':'INCOMPATIBILITY_DETECTED'})
    # 3 check-in before requested date
    c=x['checkin_events'][2]; c['event_ts']='2026-10-01T00:00:00Z'; gt.append({'scenario_id':'SCN-003','issue_type':'CHECKIN_DATE_VIOLATION','cause_code':'FORCED_EARLY_TIMESTAMP','affected_entity':'checkin_events','affected_record_id':c['checkin_event_id'],'expected_outcome':'TEMPORAL_VIOLATION_DETECTED'})
    # 4 labor allocation shift held outside period
    d=x['labor_allocations'][3]; d['labor_shift_id']='SHIFT-FAC-001-999-DAY'; x['labor_shifts'].append({'labor_shift_id':'SHIFT-FAC-001-999-DAY','facility_id':'FAC-001','shift_code':'DAY','start_ts':'2027-01-01T06:00:00Z','end_ts':'2027-01-01T14:00:00Z','workers':'1','skills':'STANDARD','status':'SCHEDULED'}); gt.append({'scenario_id':'SCN-004','issue_type':'LABOR_UNAVAILABLE','cause_code':'OUT_OF_WINDOW_SHIFT','affected_entity':'labor_allocations','affected_record_id':d['labor_allocation_id'],'expected_outcome':'LABOR_AVAILABILITY_DETECTED'})
    # 5 remove a no-show event but retain status
    ns=next(a for a in x['appointments'] if a['status']=='NO_SHOW'); e=next(e for e in x['operational_events'] if e['appointment_id']==ns['appointment_id'] and e['event_type']=='NO_SHOW'); x['operational_events'].remove(e)
    # preserve profile event volume with a distinct, meaningful audit event, not a duplicate/filler event.
    x['operational_events'].append({'event_id':e['event_id'],'appointment_id':ns['appointment_id'],'event_type':'NO_SHOW_AUDIT_RECORDED','event_ts':e['event_ts'],'sequence_no':'4','source':'SIMULATOR'})
    gt.append({'scenario_id':'SCN-005','issue_type':'MISSING_NO_SHOW_EVENT','cause_code':'REMOVED_REQUIRED_EVENT','affected_entity':'operational_events','affected_record_id':e['event_id'],'expected_outcome':'MISSING_EVENT_DETECTED'})
    for g in gt: x['exceptions'].append({'exception_id':g['scenario_id'].replace('SCN','EXC'),'appointment_id':'','issue_type':g['issue_type'],'cause_code':g['cause_code'],'severity':'HIGH','source':'CONTROLLED_INJECTION'})
    return x,gt

def export(t, out, profile, seed, ground_truth=None):
    out.mkdir(parents=True,exist_ok=True)
    for table in TABLES: write_rows(out,table,t[table])
    if ground_truth is not None:
        write_rows(out,'ground_truth',ground_truth)
    sql=[]
    for table in TABLES:
        for r in t[table]:
            cols=', '.join(r); vals=', '.join('NULL' if v=='' else "'"+str(v).replace("'","''")+"'" for v in r.values()); sql.append(f'INSERT INTO {table} ({cols}) VALUES ({vals});')
    (out/'seed_data.sql').write_text('\n'.join(sql)+'\n',encoding='utf-8')
    checks={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(out.glob('*.csv'))}
    manifest={'profile':profile,'seed':seed,'simulation_start':iso(START),'row_counts':{k:len(v) for k,v in t.items()},'sha256':checks}
    (out/'manifest.json').write_text(json.dumps(manifest,indent=2,sort_keys=True),encoding='utf-8'); return manifest

def main():
    p=argparse.ArgumentParser(); p.add_argument('--profile',choices=PROFILES,required=True); p.add_argument('--seed',type=int,default=20261022); p.add_argument('--output',type=Path,required=True); args=p.parse_args()
    base=generate(args.profile,args.seed); injected,gt=anomaly_rows(base)
    if args.output.exists(): shutil.rmtree(args.output)
    export(base,args.output/'baseline',args.profile,args.seed); manifest=export(injected,args.output,args.profile,args.seed,gt)
    from src.validation.core import validate_directory
    summary={'baseline':validate_directory(args.output/'baseline',False),'injected':validate_directory(args.output,True),'manifest':manifest}
    (args.output/'validation_summary.json').write_text(json.dumps(summary,indent=2,sort_keys=True),encoding='utf-8')
    (args.output/'reproducibility_report.md').write_text(f'# Reproducibility\n\nProfile: {args.profile}; seed: {args.seed}. Deterministic SHA-256 checksums are in `manifest.json`. Re-run the same command and compare manifests.\n',encoding='utf-8')
    print(json.dumps(summary,indent=2))
